function Input({name,label,value='',type='text',options,rows,required=true}:{name:string;label:string;value?:string|number;type?:string;options?:string[];rows?:number;required?:boolean}){return <label className="field"><span>{label}</span>{options?<select aria-label={label} name={name} defaultValue={String(value)} required={required}>{options.map(x=><option key={x}>{x}</option>)}</select>:rows?<textarea aria-label={label} name={name} defaultValue={value} rows={rows} required={required} maxLength={15000}/>:<input aria-label={label} name={name} defaultValue={value} type={type} min={type==='number'?0:undefined} required={required} maxLength={type==='text'?500:undefined}/>}</label>;}
